"use client";

import useSWR from "swr";

const fetcher = (url) => fetch(url).then((r) => r.json());

export default function NewsSection({ country = "in" }) {
  const { data, error } = useSWR(`/api/news?country=${country}`, fetcher);

  if (error)
    return (
      <div className="p-4 bg-white rounded shadow">Error loading news.</div>
    );
  if (!data)
    return <div className="p-4 bg-white rounded shadow">Loading news…</div>;

  return (
    <div className="bg-white p-4 rounded shadow">
      <h2 className="font-bold text-lg mb-2">Top Indian Headlines</h2>
      <ul className="space-y-4">
        {data.articles.map((a) => (
          <li key={a.url} className="flex items-start gap-3">
            {a.urlToImage && (
              <img
                src={a.urlToImage}
                alt=""
                className="w-16 h-12 object-cover rounded"
              />
            )}
            <div>
              <a
                href={a.url}
                target="_blank"
                rel="noopener noreferrer"
                className="font-medium hover:underline"
              >
                {a.title}
              </a>
              <p className="text-sm text-gray-500">{a.source.name}</p>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
